ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["radio_7"] = {
{"r1_d4_knox1_takes_a_car","scanner",4,4,7,13,1,{"Knox 1","Knox 1 to Knox County - show the Sheriff in service in unit 3","Dispatch","Sheriff, you're going out on patrol?","Knox 1","First time I've driven a patrol car in eleven years - somebody tell me where the siren switch moved to - never mind, I don't want to know","Knox 20","Knox 20 - Sheriff, the seat adjusts with the bar underneath, you'll want it back from the wheel","Knox 1","Seat's fine. I was smaller in 1982. Knox 1 headed to Rosewood Road to look at that motel - from a long way off","Dispatch","From a long way off, Sheriff","Knox 1","From a long way off, I'm old, Linda, I'm not stupid"}},
{"r1_d4_linda_off_the_air","scanner",4,4,21,23,3,{"Dispatch","Knox County to all units","Dispatch","The repeater batteries are reading low, I've got maybe an hour on the tower, and then I'm car-to-car only","Dispatch","Here's where everybody stands, for the log - Knox 1, Rosewood Road - Knox 20, March Ridge - Knox 9, Pruitt Lane - Knox 11, courthouse - Hardin 12, courthouse","Dispatch","Knox 4, courthouse, with blisters - Muldraugh 3, still doing laps - Knox 12, Knox 15, Knox 16 and Knox 18, not heard from","Dispatch","I wrote every one of your numbers on the board in here - I'm not erasing any of them","Knox 1","Knox 1 - Linda, come on down to the basement when the tower shuts off, there's supper down there","Dispatch","10-4, Sheriff - Knox County is going off the air at {time}","Dispatch","It's been an honor - keep your doors locked and your heads down"}},
{"r2_d4_marty_found_alternate","military",4,5,0,23,1,{"Marty","It took most of a day, and the knob on this scanner is worn smooth, but I found them again","Marty","In fairness to the Army, they did a very thorough job of hiding from a man who sells chicken feed - here's what's on the new spot","Hatchet-6","Warden Main, Hatchet-6 on alternate, commo check, over","Warden Main","Hatchet-6, Lima Charlie - keep it short on this one, our friend in March Ridge will be turning his dial, over","Hatchet-6","Roger - tell him the checkpoints say hello - Hatchet-6, out","Marty","Hello yourself, Captain, I don't actually know that you're a captain, you sound like one"}},
{"r2_d4_convoy_at_gym_doors","military",4,5,6,19,2,{"Bluejay 2-6","Warden Main, Bluejay 2-6, found your convoy, eight vehicles parked in the lot of the high school in Riverside - that's the holding area on my card, over","Warden Main","Any personnel, over?","Bluejay 2-6","Negative personnel in uniform, the trucks are backed up to the gym doors like they were unloading - tailgates down, water pallets half off, over","Warden Main","Say condition of the holding area, over","Bluejay 2-6","Gym doors are standing open, movement inside, and around the trucks - slow movement, over","Warden Main","Roger, do not land - can you see into the cab of the lead vehicle, over?","Bluejay 2-6","Driver's door open, the radio handset is hanging down on its cord - Warden Main, I think that's the open carrier we've been hearing all night, over","Warden Main","Roger, mark the grid and return to base - Warden Main, out"}},
{"r2_d4_hammer_pump_house","military",4,4,0,23,2,{"Hammer-3-7","Hammer-3-1, Hammer-3-7, radio check, over","Hammer-3-7","Hammer-3-1, this is Hammer-3-7 - radio check - how copy, over?","Hammer-3-6","Hammer-3-7, Hammer-3-6 - when did you last hear from first squad, over?","Hammer-3-7","Sir, last contact 0215, they reported movement on the fence at the water plant and said they were going to check the pump house door, over","Hammer-3-6","Anything after that, over?","Hammer-3-7","Their handset keyed twice at about 0230, no voice, over","Hammer-3-6","Roger - keep trying on the hour, I'll ask battalion for a vehicle to go look, over","Hammer-3-7","Roger, on the hour - hammer-3-1, Hammer-3-7, if you can hear me and can't talk, key your handset twice, over"}},
{"r2_d4_loudspeaker_text","military",4,7,0,23,1,{"Lockbox-6","All Lockbox stations, Lockbox-6, new loudspeaker text for the bridge, effective now - copy it word for word, over","Lockbox-6","At the fifth pole - attention, this bridge is closed by order of the United States Army - turn around now - break","Lockbox-6","At the fourth pole - stop, you are approaching an armed checkpoint, you will not be allowed to cross - turn around - break","Lockbox-6","At the third pole, this is your final warning, if you pass the burned car, you will be fired upon - break","Lockbox-6","Same order, same voice, every single time - no extras, no back-talk over the speaker, over","Lockbox-1-6","Lockbox-1-6, copy all, request permission to add please to the first one, over","Lockbox-6","Negative on please - please sounds like it's open for discussion - Lockbox-6, out"}},
{"r2_d4_north_barrier_checkbook","military",4,6,7,21,1,{"Lockbox-2-6","Lockbox-6, Lockbox-2-6, north barrier, civilian man from the Louisville side trying to walk in - says his kids are at their grandmother's in Muldraugh, over","Lockbox-6","Nobody enters - turn him around, over","Lockbox-2-6","He understands he won't be let back out, he says that's fine with him, over","Lockbox-6","It isn't his decision, the order stops traffic in both directions, over","Lockbox-2-6","Sir, he's offering to sign something, he's got a pen out and he's writing on the back of his checkbook, over","Lockbox-6","Negative - hold him at the north barrier, over","Lockbox-2-6","He's asking me what I would do, over","Lockbox-6","Don't answer that - Lockbox-6, out","Lockbox-2-6","Roger - Lockbox-2-6, out"}},
{"r2_mis_callsign_sweated_off","military_mistake",4,7,8,19,1,{"Unknown Station","Warden Main, this is, hang on","Warden Main","Station calling Warden Main, say again your callsign, over","Unknown Station","Stand by, I wrote it on my hand and it sweated off - it started with a C, over","Warden Main","Station calling, is it Crowbar, over?","Unknown Station","Could be Crowbar, we're the truck with the flat tire parked at the feed store in March Ridge, over","Warden Main","Crowbar-3-4, Warden Main, you are the truck at the feed store - send your traffic, over","Crowbar-3-4","Crowbar-3-4, the man who owns the store says he'll trade us a tire for batteries for his radio, over","Warden Main","Negative, do not give that man batteries, over","Marty","For the record, I offered the tire first, the batteries came up later"}},
{"r2_mis_calm_impostor","military_mistake",4,8,20,3,1,{"Unknown Station","All stations, this is Warden-6, the quarantine is lifted, all units go home to your families - Warden-6, out","Hatchet-6","Station claiming Warden-6, this is Hatchet-6, authenticate Kilo Papa, over","Unknown Station","Authenticate this, Captain - go home, everybody smart already did","Warden-6","All Warden stations, this is Warden-6, the previous transmission was not me, the quarantine is in effect - no unit leaves the line, over","Crowbar-6","Crowbar-6, roger - Sir, for the record, his voice was a lot calmer than yours, over","Warden-6","Crowbar-6, for the record, clear the net - Warden-6, out","Unknown Station","He's got a point, Colonel - deep breaths"}},
{"r2_mis_dead_tower_habit","military_mistake",4,9,6,20,1,{"Bluejay 2-6","Standiford Tower, Army helicopter Bluejay 2-6, ten miles south, request transition through your airspace northbound, over","Bluejay 2-6","Standiford Tower, Bluejay 2-6 - how do you hear, over?","Warden Air","Bluejay 2-6, Warden Air - why are you calling Louisville tower, over?","Bluejay 2-6","Habit, twelve years of calling that tower on the way north - my hand dialed it in before I thought about it, over","Warden Air","Understood, nobody's in that tower, Bluejay - their weather recording hasn't changed since Monday, over","Bluejay 2-6","I know, I can hear it - still says winds calm, visibility ten miles, over","Warden Air","Come back to my frequency, Bluejay - Warden Air, out"}},
{"r2_d4_labor_at_the_barrier","military",4,6,20,4,1,{"Striker-1-6","Dustoff 2-1, Striker-1-6, civilian woman at my barrier in labor, my medic says the baby is turned wrong - request urgent lift for one, over","Dustoff 2-1","Striker-1-6, is she Category One, over?","Striker-1-6","Affirmative, no bites, no fever - her husband walked her up the road from Ekron with his hands in the air the whole way, over","Dustoff 2-1","Striker-1-6, I have to take this one to Warden-6 - stand by","Dustoff 2-1","Striker-1-6, Dustoff 2-1 - Warden-6 says no civilian lift out of the county, hospitals outside will not accept her, I'm sorry, over","Striker-1-6","Then put a baby doctor on this net, the way you found me the surgeon, over","Task Force Surgeon","Striker-1-6, task force surgeon, I delivered four hundred babies before this uniform - put your medic on - tell the husband to boil water, mostly so he has a job, over","Striker Medic","Sir, Ocampo again, ready when you are, over"}},
{"r3_so_d4_rosewood_hears","sign_on",4,5,5,8,1,{"Marty","Morning, March Ridge, and morning to anybody past March Ridge who can pick this up","Marty","A fellow came to my back door yesterday and told me he heard me plain as day in Rosewood - so I'm going to assume Rosewood is listening","Marty","Rosewood, good morning, I'm sorry for whatever you're looking at out there","Marty","It's {time}, first the overnight scanner notes, then some things you can do today that don't require leaving the house"}},
{"r3_so_d4_flagpole","sign_on",4,7,5,8,1,{"Marty","Good morning, ninety-nine point six, coming to you from March Ridge on borrowed equipment","Marty","I ran the flag up the pole out front this morning, like every morning - I stood there a minute wondering if I should, then I did it anyway","Marty","If you can see a flag from your house today, somebody near you is still keeping their habits - take that for what it's worth","Marty","Here's the time. {time}, here's the news - less than I'd like"}},
{"r3_sf_d4_diesel_math","sign_off",4,6,22,2,1,{"Marty","A man who walked up to the store today asked why I don't stay on all night","Marty","The honest answer is arithmetic, I have eleven cans of diesel, the generator drinks about one a day if I'm stingy with it","Marty","I'd rather be here with you in pieces for a month than straight through for one week","Marty","So I'm going off now - good night - keep your radios turned low"}},
{"r3_sf_d4_bread_on_step","sign_off",4,7,22,2,1,{"Marty","Somebody left a loaf of homemade bread on my back step with a note that says 'For the radio man'","Marty","Nobody's ever called me that, I sell horse wormer, but I ate half of it standing up at the sink, so thank you, whoever you are","Marty","I'd share the rest if I knew who with - I don't, so I'll make it last","Marty","Off the air until six - good night"}},
{"r3_host_d4_cub_scout_canteen","host",4,6,0,23,1,{"Marty","A family came through my lot about an hour ago on bicycles - mother, father, two boys, the little one had a Cub Scout canteen on a strap","Marty","They were headed south, they asked if the Army was letting people out that way - I told them the truth, which is I don't know","Marty","The mother asked if they could fill the canteen from my hose - I said fill everything you've got","Marty","They filled the canteen and one milk jug, that was all they had to carry water in","Marty","So if you're packing to go anywhere, before the food, before the clothes, find something that holds water"}},
{"r3_host_d4_salt_river_bridge","host",4,6,0,23,1,{"Marty","I owe you a correction, yesterday I said the bridge over the Salt River at West Point was open - I had that from a man who had it from his brother","Marty","It is not open, a woman walked eight miles down here to tell me so, and then she walked eight miles back, and she was polite about it the entire time","Marty","Ma'am, I asked your name and you said not to worry about it - I'm worrying about it anyway","Marty","If you went that way on my word, I'm sorry - come back the way you went"}},
{"r3_ins_d4_driving","instruction",4,7,0,23,1,{"Marty","If you plan to drive somewhere, and some of you will, here's a few things from a man who's watched the road out front for a week","Marty","The ones in the road hear an engine from a long way off - drive in the daytime, and don't sit there idling","Marty","Don't honk, on Monday I watched a boy lean on his horn at a bunch of them outside the gas station like they'd get out of the way - they moved, toward him","Marty","Keep the tank above half, and don't count on any pump in this county - pumps need electricity, same as everything else"}},
{"r3_wx_d4_dishwater_sky","weather",4,7,5,10,1,{"Marty","Good morning, it's hazy out, and that's not all humidity, there's smoke in it from the north","Marty","If there's asthma in your house, keep the inhaler close today and keep the upstairs windows shut after all, whatever I said yesterday","Marty","The thermometer by my back door read seventy-eight at six o'clock this morning - you can do the arithmetic on this afternoon","Marty","Wind's light, out of the south, the sky is the color of dishwater","Marty","If you have work to do that makes you sweat, do it before ten or wait till after supper"}},
{"r3_mb_d4_press_box","music_bridge",4,7,8,19,1,{"Marty","About now I'd hand you over to some music, instead I'll tell you what Lloyd used to do at halftime","Marty","He'd hang the microphone out the press box window and let you hear the band a few minutes - said the crowd told you the score better than he could","Marty","I don't have a band, I've got the cicadas out back, I'm going to hold this out the window a minute","Marty","That's Knox County this {weekday}, still loud, at least up in the trees"}},
{"r3_sil_d4_loading_dock","silence",4,7,18,23,1,{"Marty","Hold on","99.6 FM","(Nothing, for almost two minutes)","Marty","Something was at the loading dock door, it's gone now, I'm going to keep my voice down the rest of the hour"}},
{"r4_sad_crossword_ink","caller_story_sad",4,8,9,20,1,{"Caller - Mae","Mr. Colburn, it's Mae Gentry in March Ridge, you knew Walter from the co-op meetings","Marty","I did, Mrs. Gentry - I, yes - go ahead","Caller - Mae","The last paper we got was Friday's - Walter did the crossword in the morning like always, in pen, because he was proud","Caller - Mae","He left about half of it, he'd finish the rest after supper, that was the routine","Caller - Mae","I read that paper every day now, the same paper, I know the grain prices by heart and they're no use to anybody","Caller - Mae","He got fourteen across wrong, wrote it in big and sure of himself, it doesn't fit with the one going down","Caller - Mae","I could fix it, I've got the pen right here","Caller - Mae","I'm going to leave it wrong, he'd want to find it himself","Marty","(Marty says nothing, paper rustles near his microphone and stops)"}},
{"r4_sad_straightening_shelves","caller_story_sad",4,8,18,22,1,{"Caller - Travis","I'm nineteen, I bag groceries at the store on Main in Muldraugh - I was the one closing Friday","Marty","All right, Travis - go ahead","Caller - Travis","Mr. Oakes, the manager, threw me the keys and said lock it up, son, I'll be right back - he went out to the lot","Caller - Travis","So I locked up, I've still got his keys on my belt loop - the big ring with the rabbit's foot","Caller - Travis","I've been going back in through the loading dock, not to take anything - well - some water","Caller - Travis","I face the shelves, you pull everything to the front so it looks full - he was real particular about the soup aisle","Caller - Travis","People came in Saturday and cleared out a lot of it - I fronted what was left, it looks okay if you don't look close","Caller - Travis","I'll keep the keys for him, he'll want the soup aisle to look right when he gets back","Marty","(Marty is quiet for a long moment)","Marty","Okay, Travis"}},
{"r4_sad_sidewalk_handprints","caller_story_sad",4,8,18,22,1,{"Caller - Wendell","Evening - Wendell from Fallas Lake, I poured a new front walk the second week of June","Caller - Wendell","While it was wet my twins pressed their hands in the end square and wrote the date with a stick - six, twelve, ninety-three","Caller - Wendell","One of them wrote the nine backwards, I was going to smooth it over but my wife said leave it","Marty","Where are your, are the twins with you?","Caller - Wendell","I'm going to leave for Brandenburg tomorrow, there's people there, they say, can't stay in this house","Caller - Wendell","I spent tonight trying to figure out how to take a square of concrete with me - you can't - I tried","Caller - Wendell","Busted the edge off, ruined a good chisel, sat down on the walk with my hands in their hands","Caller - Wendell","They fit in my palm, both of them in one palm","Marty","(Nothing from Marty but his breathing, and then that stops too)"}},
{"r4_hor_name_list_bleed","caller_story_horror",4,8,0,4,2,{"Caller - Irene","Marty, is there another station on your frequency? Right under you? Real faint?","Marty","Not that I know of, ma'am, I've got a little transmitter - I don't know what else is out there","Caller - Irene","When you stop talking, there's a man - reading names, last name, then first name - very calm, like an announcement at an airport","Caller - Irene","Adams, Ruth - Adkins, Carl - Akers, Dennis, a pause after every one - like he's giving time to write it down","Caller - Irene","I thought it was a list for the evacuation, people who got out - so I kept listening for mine","Marty","Did you hear it?","Caller - Irene","Tonight he got to the B's - Bowling, Irene - my name, then he read my husband's","Caller - Irene","And then he read our address, nobody else got an address read - just us","Caller - Irene","Then it clicked, like a tape running out, and it started over - Adams, Ruth","Marty","Ma'am, I don't, I have not heard that, I've been sitting here all night, I've not heard that","Marty","(Marty goes quiet, for a few seconds, under the carrier, there might be a voice - it is hard to tell)","Marty","I'm going to talk for a while now, I'm just going to keep talking"}},
{"r4_hor_polaroid_door","caller_story_horror",4,8,23,4,1,{"Caller - Rhonda","I went into a house on Laurel Street looking for aspirin - front door was open - nobody inside","Caller - Rhonda","On the kitchen table there's a Polaroid camera and a stack of pictures - maybe forty, lined up in rows, real neat","Caller - Rhonda","Every picture is the same bedroom door down the hall - closed, written on the white strip underneath, a time - two AM - five AM - eight AM","Marty","Like he was keeping track of something","Caller - Rhonda","Then in the next row the door's open a crack - just dark in the crack, then a little more, the times get closer together","Caller - Rhonda","The last picture, you can see fingers, around the edge of the door, at the bottom - low, like somebody's crawling","Caller - Rhonda","The strip on that one doesn't have a time on it - it just has a line where the pen slid off","Caller - Rhonda","I looked down the hall, Marty, at the real door","Marty","Ma'am, you don't have to tell me that part","Caller - Rhonda","It was wide open, I didn't take the aspirin, I left the pictures in their rows","Marty","(Marty says he needs a minute and the air goes still)"}},
{"r4_hor_pay_phone_ring","caller_story_horror",4,8,23,4,1,{"Caller - Deb","All the phones are dead, right? Every line in the county - that's what everybody says","Marty","Mine's been dead since Sunday","Caller - Deb","The payphone at the gas station on the Brandenburg road rings - around midnight - eleven rings, I've counted every night","Caller - Deb","Tonight I ran out and picked it up on the ninth ring - I don't know why I did that, I think I wanted it to be my mom","Marty","Was anybody there?","Caller - Deb","The line was open, no dial tone, and on the other end, a room - a big room, you could hear it was big","Caller - Deb","A lot of feet shuffling on a hard floor - a lot, and way in the back, a telephone ringing - ringing and ringing, and nobody picking it up","Caller - Deb","I said hello, and all the shuffling stopped","Caller - Deb","I hung up - I ran, I'm in my car with the doors locked and I'm calling you from the CB","Marty","(Marty swallows audibly, he says he's there, he says it again)"}},
{"r4_hor_mannequin_store","caller_story_horror",4,8,22,3,1,{"Caller - Wade","You know the dress shop in West Point with the window mannequins? Ladies' clothes, fancy?","Marty","I don't shop there, but I've passed it","Caller - Wade","There's three mannequins in that window, summer dresses, sun hats, I walk past it every night going to check my mother's house","Caller - Wade","Tonight there were four","Marty","Four","Caller - Wade","Same pose, same kind of dress, pulled off the rack, on crooked - a sun hat, standing real still with the other three","Caller - Wade","I stood there in the street with my flashlight on the window, telling myself somebody moved one out from the back","Caller - Wade","And the fourth one had a price tag hanging off the sleeve - and the price tag was swinging - back and forth, in a shop with no air moving","Caller - Wade","It's breathing, Marty, that's why the tag swings, it's standing there in a dress with its eyes open, breathing","Marty","(Marty whispers something that isn't meant for the microphone)","Marty","Go another way to your mother's, please, tomorrow, go another way"}},
{"r4_hor_twin_reflection","caller_story_horror",4,8,0,4,1,{"Caller - Glenda","We boarded up every window downstairs but the big one in the den - too big, we hung a quilt over it","Caller - Glenda","Tonight my boy lifted the corner of the quilt to look out - nine years old, you can't stop them","Caller - Glenda","He said Mama, there's a boy out there looking in - just like me, I said honey, that's your reflection - the candle's behind you","Marty","And was it?","Caller - Glenda","He laughed and let the quilt drop - and then he said, Mama, how come it waved at me first?","Caller - Glenda","I said no, baby, you waved first, a reflection can't go first - that's what I told him","Caller - Glenda","And he said, I didn't wave, Mama, I was just looking","Caller - Glenda","Something is scratching at the glass behind the quilt now - low down, about as high as a nine-year-old","Marty","(Marty tells her to take the boy upstairs, and his voice is not steady when he does)"}},
{"r5_host_marty_legal_pad","host",4,8,0,23,1,{"Marty","Pardon the paper rustling, I've written this down on a legal pad, because my hands won't settle and my head is worse","Marty","What I've heard myself: gunfire toward Rosewood around eleven last night, then nothing - a car horn stuck on north of town for most of an hour - it quit around two","Marty","What I've been told and can't confirm: that the Army is letting people out through Fort Knox - I don't know that - please don't walk anywhere on my say-so","Marty","Someone left a fifty-pound sack of sweet feed at my back door this morning, with a note - it says, 'Thank you for staying on'","Marty","I don't know who you are, I have four hundred sacks of sweet feed - but I thank you for it, truly","Marty","That's the report, I'll be back when I've got something honest to add to it"}},
{"r7_mil_no_new_soi_page","military_mistake",4,7,0,23,1,{"Cardinal-2-6","Cardinal Main, 2-6, the signal instructions I've got run out at midnight tonight - I don't have the next page, over","Cardinal Main","2-6, nobody has the next page, it comes from Frankfort in a courier bag and there hasn't been a courier since the eighth, over","Cardinal-2-6","So at midnight the whole battalion's frequencies expire, over?","Cardinal Main","At midnight we keep using the page we've got, that's the decision and I made it about an hour ago, over","Cardinal-2-6","Roger - Main, anybody with a scanner and a week's patience has had our frequencies for a while now, over","Cardinal Main","I'm aware. 2-6, assume anything you say on this net is heard by everybody in this county, because it is, over","Cardinal-2-6","Understood, then I'll talk on it like my mother's listening. 2-6, out"}},
{"r7_mil_ammunition_by_magazine","military",4,7,0,23,1,{"Cardinal Main","All Cardinal stations, report ammunition on hand - count it by magazine, not by case, over","Cardinal-1-6","Cardinal-1-6, fourteen magazines across nineteen soldiers, over","Cardinal-3-6","Cardinal-3-6 - twenty-two magazines, four of them are the ones we found in a truck and I don't trust the springs, over","Cardinal Main","Roger both - Cardinal-1-6, your soldiers without a magazine still carry the weapon, over","Cardinal-1-6","Main, a rifle with nothing in it is a stick, over","Cardinal Main","It's a stick that makes a civilian stop his car - that's most of what we've been doing with them anyway, over","Cardinal-1-6","Roger that - Main, when does anybody bring ammunition into this county, over?","Cardinal Main","1-6, I have asked that question up the net eleven times - Cardinal Main, out"}},
{"r7_nights_teague_out_of_service","scanner",4,6,2,6,2,{"Knox 20","Knox County, Knox 20","Dispatch","Go ahead, Sarge","Knox 20","Show Knox 26 out of service at {time}","Dispatch","Out of service - do you need anything, Knox 20?","Knox 20","I need the rest of the shift to stay on the air - that's all I need","Dispatch","Copy that","Knox 20","Bonnie, his mother's number's in the book under Teague on Halbert Street - don't call it tonight - let her have the night out","Dispatch","I won't call it tonight"}},
{"r7_nights_laid_out_in_the_ditch","scanner",4,6,0,5,2,{"Dispatch","Knox 22, report of a body in the ditch on 31W just south of the lumber yard - caller didn't stop, called from the truck stop","Knox 22","Knox 22 en route - did they say male or female?","Dispatch","They said they didn't look twice","Knox 22","Knox 22, I'm 10-23, dispatch, it's a man and it wasn't a wreck - he's laid out straight with his hands folded on him","Dispatch","Say again, 22?","Knox 22","Somebody laid him out, folded his hands, put a coat over his face... off the road, in the weeds - a person did that","Dispatch","Do you want the coroner?","Knox 22","I want whoever laid him out, they took the time to do it right and then they went on - that's who I'd like to talk to"}},
{"r7_nights_notebook_paper_log","scanner",4,7,2,6,1,{"Dispatch","Knox 20, I'm out of call cards, I've been writing on my boy's notebook paper since midnight","Knox 20","Number the pages","Dispatch","I am numbering them, I'm on page thirty-one","Knox 20","Thirty-one pages since midnight","Dispatch","Thirty-one - Sarge, I quit writing down the ones where nobody's hurt - there ain't room for those anymore","Knox 20","Write the ones where somebody's hurt and write the addresses out full - somebody's gonna want to read this someday","Dispatch","Who?","Knox 20","I don't know - write it anyhow"}},
{"r7_ksp_post_on_generator","scanner",4,6,5,23,1,{"Post 4","All units, Post 4 is on generator as of about an hour ago - radio's up, teletype's down, and the phones come and go","Trooper 418","Post 4, 418 - how long will the generator run?","Post 4","The mechanic says forty hours on what's in the tank - after that it depends on whether anybody brings us diesel","Trooper 418","What do we do if the radio quits?","Post 4","You come to the post, every four hours, whoever's closest comes to the post and puts his face in the door","Trooper 422","422 copies, post 4, that's forty miles for me each way","Post 4","Then make it eight hours for you, 422, and don't make me guess about you in between"}},
{"r7_ksp_relay_through_post5","scanner",4,6,0,8,1,{"Post 4","Post 5, Post 4 - do you have anything on the low band out of Meade County? We can't raise our unit at Brandenburg","Post 5","Post 4, Post 5, we hear him faint - stand by and I'll try him for you","Post 5","Post 4, Post 5, your man says he's 10-23 at the river road and he's got a boat ramp full of people wanting across","Post 4","Ask him how many and ask him if anybody's got a boat","Post 5","He says a hundred and some, and one johnboat, and a fella charging money for it","Post 4","Tell him we're aware, we've got nothing to send, and he's to use his own judgment on the fella charging money","Post 5","He copied that and he laughed at it, post 4, we'll keep relaying for you as long as we're up - post 5 clear"}},
{"r7_ksp_insulin_run","scanner",4,6,6,14,2,{"Post 4","Trooper 418, this isn't police work but it's what I've got - there's insulin at the pharmacy in Elizabethtown for a family out at Ekron","Trooper 418","418, I'll run it - cold pack?","Post 4","The pharmacist's got it in a cooler with a note rubber banded to the lid - name on it is Tandy","Trooper 418","Copy - post 4, how many days is in the cooler?","Post 4","Eleven days worth, he said that's everything he's got left of that kind and he don't expect a truck","Trooper 418","418 en route with it, I'll hand it to somebody at that house and I'll write down who I handed it to","Post 4","Do that, 418, I want that name on a piece of paper in this building"}},
{"r7_ksp_nobody_to_book","scanner",4,6,11,23,1,{"Trooper 435","Post 4, 435, I've got two in custody out of a house on the parkway access road - they were carrying a television down a driveway","Post 4","435, whose house?","Trooper 435","Nobody's, owner's been gone since the fourth and the front door's laid in the yard","Post 4","Any place to take them?","Trooper 435","That's my question for you, and before you answer it, one of them is about sixteen and the other one's his mother","Post 4","435, what do you want to do?","Trooper 435","I want to take the television out of the driveway, put it back in the house, and drive them home - and I want you to say that's all right","Post 4","That's all right, 435, log it as a warning and go on to your next one"}},
{"r7_fire_booster_tank_only","scanner",4,6,7,23,1,{"Car 3","All units, Car 3, new rule as of today, and I'll say it slow - you get what's in your tank - that's it, that's all the water there is","Engine 32","Engine 32, that's five hundred gallons on this truck","Car 3","Then you've got about two minutes of a working line - use it to get somebody out a window, not to put a fire out","Tanker 44","Tanker 44, I carry eighteen hundred - do I still shuttle?","Car 3","You shuttle when there's a life in it, not for a barn, not for a shed, not for a car","Engine 32","Car 3, folks are gonna stand in the yard and watch us not put their house out","Car 3","They are, and you're going to stand there and take what they say to you, and you're not going to say one word back - car 3 out"}},
{"r7_fire_farmer_burning_a_barn","scanner",4,7,19,23,1,{"Dispatch","Brush 32, we've got a barn going on the Kelso place off Echo Creek Road - caller says it's a big one","Brush 32","Brush 32 en route, dispatch, that barn's been standing empty since the old man died","Brush 32","Dispatch, Brush 32 on scene, this here's on purpose, there's a man in the lot with a can of diesel and he's watching it burn","Dispatch","Is he all right?","Brush 32","He's all right, he says there was eleven of them in that barn and he shut the door on them and he didn't know what else to do with them","Dispatch","Brush 32, do you need the sheriff?","Brush 32","No, there's no fence within a hundred yards of it and no wind - I'm gonna stand here with him till it falls in","Dispatch","Copy, Brush 32 - anything you want me to log?","Brush 32","Log that it was a controlled burn, that's what it is - he controlled it"}},
{"r7_fire_lost_the_pumper","scanner",4,6,12,23,2,{"Engine 21","Car 3, Engine 21, we're leaving the truck - say again, we are leaving Engine 21 at 909 Dixie and coming out on foot","Car 3","Engine 21, say again your last?","Engine 21","There's a crowd of them coming up the street between us and the cab - six of us are on the roof of the garage next door","Car 3","Is the pump engaged?","Engine 21","Pump's engaged and the line's charged and the tank's about empty, so it's about to run dry and howl","Car 3","Then let it howl, it'll pull them to the truck and away from you - go over the back of that garage and walk east","Engine 21","Copy east, car 3, that's a 1979 pumper and this department paid for it with fish fries","Car 3","I know what it cost, six men off a roof is worth a pumper - go east, 21"}},
{"r7_fire_mutual_aid_nobody","scanner",4,6,9,23,1,{"Car 3","Dispatch, Car 3 - call mutual aid - everybody - Hardin, Meade, Bullitt, anybody that answers a phone","Dispatch","Car 3, I've been dialing for twenty minutes - Meade County's line rings busy - Hardin says they're committed","Car 3","Committed to what?","Dispatch","Their dispatcher said and I wrote it down, committed to their own county until further notice","Car 3","That's a real polite way of saying we're on our own","Dispatch","It is - car 3, what do I tell the next caller?","Car 3","Tell them the honest thing, tell them get everybody out of the house and stand in the road, and we'll come when we can come"}},
{"r7_ems_leave_them_where_they_are","scanner",4,6,7,23,1,{"Dispatch","EMS 1, I've got a call at 78 Pruitt Lane - caller says her husband's been dead since morning and she'd like somebody to come","EMS 1","Dispatch, is there anybody there hurt?","Dispatch","No, she just wants somebody to come","EMS 1","Copy - put it behind the ones where somebody's alive and I'll take it when I can take it","Dispatch","EMS 1, that puts her tomorrow at the earliest","EMS 1","I know what it puts her","Dispatch","She asked me if it was all right for her to sit in the room with him while she waits","EMS 1","Tell her yes - tell her it may be tomorrow - and tell her I said her name on the radio... what's her name?","Dispatch","Lurlene Kelso","EMS 1","Lurlene Kelso, 78 Pruitt Lane - EMS 1 copies and I'll come"}},
{"r7_school_the_attendance_book","scanner",4,7,8,20,1,{"Base","Base to Bus 12 - Wanda, where's your attendance book?","Bus 12","It's on the dash - why?","Base","A woman's been at the garage since eight this morning looking for her boy - she says he got on a bus at the elementary on Wednesday","Bus 12","Base, what's his name?","Base","Dwight - Dwight Pruitt, nine years old, red tennis shoes","Bus 12","Stand by, Base","Bus 12","Base - page four - Dwight Pruitt, went off at the fairgrounds with a woman who wrote her own name as Glenda Tandy and put down an address on Tanner Road","Base","Say that address again, Bus 12, slow, she's standing right here at my elbow","Bus 12","Tanner Road. 4290 Tanner Road, base, tell her the boy asked for a window seat and he got one"}},
{"r7_school_last_bus_out","scanner",4,5,17,22,1,{"Base","Base to all buses - last trip, whoever's got room, come back by the elementary one more time before dark","Bus 12","Bus 12, I've got about twelve seats, I'm ten minutes out","Base","Bus 12, take the gym doors, there's nineteen left inside and two of them won't come","Bus 12","Won't come why?","Base","An old couple out of Halbert Street, they say their grandson knows to look for them at that school and they aim to be there when he does","Bus 12","Base, what do you want me to do?","Base","Take the seventeen, leave the two a case of water and the flashlight out of your kit and tell them which door don't latch","Bus 12","Copy, base, I'll come back by in the morning and ask them again","Base","I know you will, so will I"}},
{"r8_hor_chairs_to_window","caller_story_horror",4,60,22,4,2,{"June","Line's open, it's late, so take it slow if you need to","Wanda","First time calling, I been sitting on this since Thursday and my husband's tired of hearing it","Wanda","My mother's place out past the grain bins on Tanner Road - I went for her pressure pills","Wanda","House was right, I mean right, dishes done, dish towel folded over the oven handle the way she does it","June","Was she there?","Wanda","No, and that ain't the part, every chair in that kitchen was turned around facing the window","Wanda","Six chairs, facing out at the yard, nobody sat in 'em - they was just turned","June","You don't know who turned them","Wanda","I ain't saying I know, I got the pills and I did not go upstairs - that's all I know and all I'm saying"}},
{"r8_hor_four_plates_three_chairs","caller_story_horror",4,45,0,4,1,{"Darlene","I shouldn't be dumping this on you - it's late - sorry","June","It's what the hour's for - go ahead","Darlene","Brick house on the Irvington road, we went in for canned goods, me and my brother in law","Darlene","Table's set, four plates, forks on the napkins, glasses turned right side up - somebody's Sunday plates, the good ones with the gold rim","Darlene","Three chairs, there's four plates and three chairs","June","Maybe a chair got moved","Darlene","That's what he said, I keep coming back to the chairs though, I lay there at night doing the arithmetic on it","Darlene","Probably nothing, probably somebody carried a chair off - I moved my bedroll in off that side of the house anyhow"}},
{"r8_hor_machine_loop_glass","caller_story_horror",4,50,0,4,1,{"Clyde","House had power off a generator in the garage, still had fuel in it, that's why I stopped","June","Go on","Clyde","Their answering machine was going, little tape kind, the light blinking, playing the messages over","Clyde","No voice at all, four seconds of somebody setting a glass down on wood","Clyde","Then it clicks and does it again, set the glass down - click, set the glass down","June","How many times?","Clyde","I stood there for it eleven times, then I pulled the cord out of the wall and the tape kept turning a second, which I did not care for","Clyde","That's all that happened, I took the gas can and I did not take the machine"}},
{"r8_hor_it_stops_when_you_stop","caller_story_horror",4,50,1,5,1,{"Maxine","Walking the fence line at dusk, checking for breaks, I do that every evening, it's nothing","June","Go on","Maxine","Something walking in the brush on the other side, keeping up with me - which, fine, that's a deer, that's a dog","Maxine","I quit walking and it quit, I walked, it walked","Maxine","I done that four times before I run, four times, like a fool, testing it","June","Did it follow you in?","Maxine","I didn't turn around to find out, I got in and put the bar across the door","Maxine","And I'll tell you the part I can't get shed of - it stopped before I did, the last time, it stopped first"}},
{"exp_lunchbox_note","caller_story_sad",5,3650,0,23,1,{"Irene","My boy used to hide my notes so his friends wouldn't see","June","The ones you put in his lunch?","Irene","Yes, I thought he'd thrown them away","Irene","Found a stack in his desk when I was looking for batteries","June","What did the notes say?","Irene","Nothing important, good luck on a test - don't forget your sweater","June","He kept them, though","Irene","Every single one had been folded small enough to fit his palm"}},
{"exp_truck_driver_directions","instruction",5,3650,0,23,1,{"Wade","People keep giving directions using stores that might not have signs anymore","June","What would you rather hear?","Wade","Whether they actually traveled the road - and when","June","Not just that they knew it before?","Wade","I knew a hundred roads before, doesn't tell me which one has a truck across it today","June","That's worth remembering when people call in","Wade","Please don't call a route clear because it used to be your shortcut","June","We won't treat an old habit as a current road report"}},
{"more_radio_blanket_shift","caller_story_sad",5,3650,21,5,1,{"Ruth","Somebody put a blanket over me while I slept","Ruth","Nobody's admitting to it","Ruth","Asked three times, they all suddenly need to look at something else","Ruth","I keep looking at everybody like they've done something","June","Any guesses?","Ruth","The roughest man here says it was a ghost","June","A ghost brought you a blanket - all right","Ruth","It smelled of his cigarettes","Ruth","Same little burn hole his coat's got - some ghost","Ruth","I'll stop asking, he's embarrassed enough, poor man"}},
{"more_radio_father_snoring","caller_story_sad",5,3650,22,5,1,{"Kit","My father snores like a truck backing over a fence","June","You're trying to sleep?","Kit","No, I'm trying not to laugh","Kit","If I start, he'll wake up and say he wasn't snoring","Kit","He was so frightened earlier, wouldn't admit it","Kit","Now he's making this ridiculous noise and I know he's asleep","Kit","I keep looking over, he looks so... stupid, in a good way - does that make sense?","June","I think so, my dad used to fall asleep with his mouth wide open","June","Try to get some rest yourself","Kit","I'll try, oh-- there he goes again, that's got to hurt his throat"}},
{"more_radio_fence_paint","caller_joke",5,3650,0,23,1,{"Roy","My neighbor says we need a committee","June","For what?","Roy","The color of a fence","June","How many colors of paint have you got?","Roy","One","June","One color? Roy, what's there to meet about?","Roy","No, he doesn't like the one","June","What's his alternative?","Roy","He says, 'Wait until circumstances improve.' That's how he talks now","June","I'd paint it before he starts writing minutes"}},
{"more_radio_small_good_news","host",5,3650,0,23,1,{"June","We're taking small good news for a minute","Lou","Found the screw for my glasses","Lou","Under my heel, would you believe? Nearly walked off with it","Celia","I got a stain out of a shirt","June","How? I've got one that won't-- sorry - go on, Roy","Roy","My brother apologized without adding 'but'","June","Roy, I said small news, we aren't equipped for miracles","Anne","I laughed before I remembered I was sad","Anne","Sorry, that sounds strange, I was halfway through laughing and then I felt bad","June","No, I think I know what you mean, thank you for calling"}},
{"more_radio_prison_nickname","caller_story_sad",5,3650,0,23,1,{"Vic","I told a woman my name today and she used it","Vic","Not the one they used inside, my actual name","Vic","Didn't even answer at first, was waiting for somebody else to say something","Caller","What'd you do?","Vic","Asked her to say it again","Caller","She think you were being strange?","Vic","Yeah, probably, she said it slower, like I was hard of hearing","Vic","I'm not telling this so anybody feels sorry for me","Caller","Nobody said you were","Vic","All right - good, just wanted to tell somebody"}},
{"more_radio_prison_recipe","caller_joke",5,3650,0,23,1,{"Vic","I once made a birthday cake in a plastic bowl","Caller","What was in it?","Vic","Cookies - candy - Uhhh-- some kind of creamer? It was a long time ago","Caller","Did anybody eat it?","Vic","All of it, birthday boy asked for the recipe","Caller","You give it to him?","Vic","Couldn't remember what I'd put in it, kept adding shit till it stayed together","Caller","Must've been good","Vic","It was mostly sweet and we were mostly bored","Vic","Don't ask me to do it again, wouldn't risk it twice"}},
{"more_radio_trucker_seat","caller_story_sad",5,3650,0,23,1,{"Earl","Passenger seat keeps making a noise","June","Something loose?","Earl","Spring, I could fix it in five minutes","Earl","Got the tools right beside me, been meaning to-- well, I haven't","Earl","My brother used to shift around in that seat the whole trip","June","Couldn't get comfortable?","Earl","Couldn't leave anything alone, had an opinion about every road sign","Earl","Sometimes I hear that squeak and start to say something to him","Earl","Just for half a second, over a bump","Earl","Then I look over - anyway, that's why I haven't fixed it"}},
{"king_radio_other_shoe","caller_joke",5,3650,0,23,1,{"Walt","I've got a complaint about the end of the world","June","Just the one?","Walt","Nobody's interested in my missing sock anymore","June","Walt, I wasn't interested before","Walt","See, that's the continuity I was looking for","June","Are you wearing the other one?","Walt","Of course. I'm not giving up on the pair","June","Good. We'll keep an ear out"}},
{"king_radio_forgot_joke","caller_joke",5,3650,0,23,1,{"Ben","I called with a joke and I've forgotten it","June","Any of it left?","Ben","There was a horse. Maybe a doctor","June","That could go a few ways","Ben","I was laughing so hard before I called","June","I believe you","Ben","Well, that's all I had","June","Honestly, Ben, it's cheered me up a little"}},
{"king_radio_graduation","caller_story_sad",5,3650,0,23,1,{"Martha","My boy hated it when I clapped too loud at school","June","What did he do?","Martha","Looked everywhere but at me. Like that helped","June","Were you the loudest?","Martha","Didn't seem worth going if I wasn't","June","I think he knew that","Martha","If I see him again, he's getting it worse","June","I hope he gets to complain about it"}},
{"king_radio_old_storm","caller_story_sad",5,3650,0,23,1,{"Hank","Bad storm when I was little. We slept in the hallway","June","Your whole family?","Hank","Six of us. Kept kicking each other. Mom got furious","June","Did you get much sleep?","Hank","Don't remember. Just her telling us to settle down","June","Funny what stays","Hank","Yeah. Wouldn't mind being told to settle down again","June","I hear you"}},
{"knox_tired_uniform","scanner",5,14,0,23,1,{"Unit Nine","Is anybody still using the shift board?","Unit Four","I'm not even sure anybody's in that room","Unit Nine","Then who am I reporting to?","Unit Four","Right now? Me, I suppose - I'm listening"}},
{"r2_d5_marty_notebook_page","military",5,7,7,21,1,{"Marty","For three days I've written the same name at the top of my notebook page - Packhorse-5, it was a supply convoy - nine trucks","Marty","I didn't know a single one of those soldiers, I'd started pulling for them anyway, the way you pull for a horse at the fair because you liked its name","Marty","The Army found the trucks, parked at the school in Riverside with the tailgates down - they had made their delivery","Marty","That's all I'll say about it, I'm going to leave the top of tomorrow's page blank"}},
{"r2_d5_hammer_walk_denied","military",5,5,0,23,1,{"Hammer-3-7","Hammer-3-6, Hammer-3-7, status on the vehicle for the water plant, over","Hammer-3-6","Battalion says negative, no vehicles come off the line, first squad is carried as missing, over","Hammer-3-7","Sir, request permission to walk it - four miles, me and two volunteers, over","Hammer-3-6","Denied, I'm not trading three for nine, over","Hammer-3-7","They're not a trade, sir, they're first squad, over","Hammer-3-6","I know who they are, Sergeant - Denied - keep calling on the hour, over","Hammer-3-7","Roger, hammer-3-1, Hammer-3-7, radio check, over","Hammer-3-7","Hammer-3-1, Hammer-3-7, nobody's forgotten you out there - radio check, over"}},
{"r2_d5_guard_courtesy_call","military",5,6,18,23,1,{"Thoroughbred 2-6","Hatchet-6, Thoroughbred 2-6, eighteen hundred personnel count - twenty-two present out of forty, over","Hatchet-6","Where are the other eighteen, over?","Thoroughbred 2-6","Home, sir - Brandenburg, Irvington, Ekron, they took one truck and left their rifles stacked by the road, over","Hatchet-6","You'll report them absent without leave, over","Thoroughbred 2-6","Negative, sir, I'll report them gone to protect Kentucky, that's what the Guard is for, over","Hatchet-6","Thoroughbred 2-6, you will hold that road with what you have left, over","Thoroughbred 2-6","I'll hold it until relief or midnight, whichever comes first - at midnight I'm going to Irvington too, my daughter is eleven, over","Hatchet-6","Thoroughbred, this is not a negotiation, over","Thoroughbred 2-6","No, sir, it's a courtesy call - Thoroughbred 2-6, out"}},
{"r2_d5_airdrop_trailer_park","military",5,6,9,18,1,{"Hauler 3-3","Warden Main, Hauler 3-3, two minutes out from the release point over the Muldraugh ball field, over","Warden Main","Hauler 3-3, Sandlot reports the field clear of civilians, wind out of the southwest, gusting, over","Hauler 3-3","Copy gusting - green light - Bundles away, six chutes, over","Sandlot","Warden Main, Sandlot, I have four chutes coming down on the field, two drifting east over the rooftops, over","Warden Main","Where are the two landing, over?","Sandlot","One's hung up on the steeple of the Methodist church - the other went down in the trailer park behind the car wash, over","Warden Main","What was in the trailer park bundle, over?","Sandlot","According to the manifest, antibiotics and baby formula, over","Warden Main","Roger - hold your people at the field, no recovery team, over","Sandlot","Too late for that, Warden Main, half the trailer park is already running for it, over"}},
{"r2_d5_relay_hill_fence","military",5,7,20,4,1,{"Relay Hill","Warden Main, Relay Hill, movement coming up the service road to the antenna site, over","Warden Main","Relay Hill, how many personnel on site, over?","Relay Hill","Two, me and Specialist Varga - and a generator that's louder than both of us put together, over","Warden Main","If you shut the generator down, the retrans goes off the air, over","Relay Hill","I know that, that's why I'm calling instead of shutting it down - your whole line talks through this hill, over","Warden Main","Keep it running, get in the shelter and lock the door, a reaction force is on the way, over","Relay Hill","Roger - how long, over?","Warden Main","Stand by","Relay Hill","Warden Main, they're at the fence - Varga says to tell you the antenna's still good, over","Warden Main","Roger - Reaction force is forty minutes out - keep talking to me, Relay Hill, over"}},
{"r2_d5_listening_silence_marty","military",5,5,5,11,2,{"Warden-6","All Warden stations, Warden-6, at 0340, armed civilians hit TCP 4 at the exact minute of shift change - they knew the time because we said it on this net, over","Warden-6","Effective now, radio listening silence on all nets except contact and medical - no times - no names - no counts, acknowledge by double click only","Crowbar-6","Crowbar-6, roger silence - Sir, how bad was TCP 4, over?","Warden-6","Crowbar-6, what did I just say? Double click only - Warden-6, out","Marty","I'm turning the scanner off for today, they said the men who hit that roadblock learned the shift change from the radio","Marty","I can't tell you whether they heard it on this station - I have played that net for three days, I have to consider that they did","Marty","So there'll be no Army traffic from me until tomorrow - keep your doors locked, that one I can still say"}},
}
